            <option value="zh">中文</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-4">
        <h5>Preview</h5>
        <div class="appearance-preview @PreviewThemeClass" style="@PreviewStyle">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">
                This is how your content will look with the selected settings.
                The quick brown fox jumps over the lazy dog.
            </p>
            <div class="preview-meta">
                Theme: @Theme · Font: @FontSize · Language: @LanguageDisplayName · Compact: @(CompactMode ? "On" : "Off")
            </div>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
        @(IsSaving ? "Saving…" : "Save")
    </button>

    @if (ShowSuccess)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">Appearance saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Appearance { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "System";
    private string FontSize = "Medium";
    private string Language = "en";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Appearance is not null && !_initialized)
        {
            Theme = Appearance.Theme;
            FontSize = Appearance.FontSize;
            Language = Appearance.Language;
            CompactMode = Appearance.CompactMode;
            _initialized = true;
        }
    }

    private bool _initialized;

    private string PreviewThemeClass => Theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string PreviewStyle
    {
        get
        {
            var size = FontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.15rem",
                _ => "1rem"
            };
            var padding = CompactMode ? "0.5rem" : "1rem";
            return $"font-size: {size}; padding: {padding};";
        }
    }

    private string LanguageDisplayName => Language switch
    {
        "en" => "English",
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => Language
    };

    private async Task Save()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

