arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_6d9b68f3779c43a782ce066a565fc3f1.Models
@using sv_6d9b68f3779c43a782ce066a565fc3f1.Services
@using sv_6d9b68f3779c43a782ce066a565fc3f1.Components.Pages.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@ActiveSection" OnSectionSelected="section => ActiveSection = section" />

    <div class="settings-content">
        @if (IsLoading)
        {
            <div class="d-flex justify-content-center p-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection Profile="@Profile" OnSave="SaveProfile" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@NotifPrefs" OnSave="SaveNotifications" />
                    break;
                case "Security":
                    <SecuritySection Security="@Security"
                                     OnChangePassword="HandleChangePassword"
                                     OnRevokeSession="HandleRevokeSession" />
                    break;
                case "Appearance":
                    <AppearanceSection Appearance="@AppearancePrefs" OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile? Profile;
    private NotificationPrefs? NotifPrefs;
    private SecuritySettings? Security;
    private AppearanceSettings? AppearancePrefs;

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        Profile = profileTask.Result;
        NotifPrefs = notifTask.Result;
        Security = securityTask.Result;
        AppearancePrefs = appearanceTask.Result;

        IsLoading = false;
    }

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        Profile = updated;
    }

    private async Task SaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        NotifPrefs = updated;
    }

    private async Task HandleChangePassword((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        AppearancePrefs = updated;
    }
}

/* Settings page layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.settings-sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.settings-nav-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

/* Profile avatar */
.profile-avatar-area {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem;
    transition: all 0.2s;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-system {
    background: #f0f0f5;
    color: #333;
}

.preview-header {
    font-weight: 700;
    margin-bottom: 0.5rem;
    font-size: 1.1em;
}

.preview-text {
    margin-bottom: 0.5rem;
    line-height: 1.5;
}

.preview-meta {
    font-size: 0.8em;
    opacity: 0.7;
    border-top: 1px solid currentColor;
    padding-top: 0.5rem;
    margin-top: 0.5rem;
}

/* Success toast animation */
.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* Modal backdrop fix for scoped display */
.modal-backdrop.show {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1040;
}

.modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

